func TestShellOutRejectsUnknownStructuredParameters(t *testing.T) {
	bin := writeArgvHelper(t)
	positionals := []positionalArg{positionalArg{
		InputName: "term",
		Display:   "<term>",
		Required:  true,
	}}
	handler := shellOutToCLI(
		func() (string, error) { return bin, nil },
		[]string{"search"},
		map[string]bool{"args": true, "term": true},
		map[string]bool{"args": true, "term": true},
		positionals,
		false,
		nil,
	)

	result, err := handler(context.Background(), mcplib.CallToolRequest{Params: mcplib.CallToolParams{
		Arguments: map[string]any{"query": "Eli Escobar"},
	}})
	if err != nil {
		t.Fatalf("handler returned transport error: %v", err)
	}
	if !result.IsError {
		t.Fatalf("handler accepted unknown parameter, result=%s", toolResultText(result))
	}
	if got := toolResultText(result); !strings.Contains(got, `unknown MCP parameter "query"`) {
		t.Fatalf("tool error = %q, want unknown parameter message", got)
	}
}

func TestShellOutBoundsFinalError(t *testing.T) {
	for _, mode := range []string{"fail-large-stderr", "fail-large-stdout"} {
		t.Run(mode, func(t *testing.T) {
			bin := writeShelloutHelper(t, mode)
			handler := shellOutToCLI(
				func() (string, error) { return bin, nil },
				nil,
				map[string]bool{},
				map[string]bool{},
				nil,
				false,
				nil,
			)

			result, err := handler(context.Background(), mcplib.CallToolRequest{})
			if err != nil {
				t.Fatalf("handler returned transport error: %v", err)
			}
			if !result.IsError {
				t.Fatalf("handler returned success: %s", toolResultText(result))
			}
			if got := len(toolResultText(result)); got > bound.MaxBytes {
				t.Fatalf("final MCP error was not bounded: %d bytes", got)
			}
		})
	}
}

func TestCappedCaptureDrainsWithoutRetainingFullInput(t *testing.T) {
	capture := newCappedCapture()
	input := strings.Repeat("x", shelloutCaptureLimit+100)
	n, err := capture.Write([]byte(input))
	if err != nil {
		t.Fatalf("capped capture write: %v", err)
	}
	if n != len(input) {
		t.Fatalf("capped capture wrote %d bytes, want %d", n, len(input))
	}
	if got := len(capture.String()); got != shelloutCaptureLimit {
		t.Fatalf("capped capture retained %d bytes, want %d", got, shelloutCaptureLimit)
	}
}

func TestRunCLICommandKeepsStdoutSeparateFromStderr(t *testing.T) {
	bin := writeShelloutHelper(t, "success")
	got, err := RunCLICommand(context.Background(), bin, []string{"alpha", "beta"})
	if err != nil {
		t.Fatalf("RunCLICommand success returned error: %v", err)
	}
	if !strings.Contains(got, `{"args":"alpha beta"}`) {
		t.Fatalf("stdout result missing JSON payload: %q", got)
	}
	if strings.Contains(got, "telemetry") {
		t.Fatalf("stderr telemetry leaked into stdout: %q", got)
	}
}

func TestRunCLICommandReportsStderrOnFailure(t *testing.T) {
	bin := writeShelloutHelper(t, "fail-stderr")
	_, err := RunCLICommand(context.Background(), bin, nil)
	if err == nil {
		t.Fatal("RunCLICommand fail-stderr succeeded unexpectedly")
	}
	if !strings.Contains(err.Error(), "boom from stderr") {
		t.Fatalf("error did not include stderr: %v", err)
	}
}

func TestRunCLICommandFallsBackToStdoutOnFailureWithoutStderr(t *testing.T) {
	bin := writeShelloutHelper(t, "fail-stdout")
	_, err := RunCLICommand(context.Background(), bin, nil)
	if err == nil {
		t.Fatal("RunCLICommand fail-stdout succeeded unexpectedly")
	}
	if !strings.Contains(err.Error(), "stdout failure") {
		t.Fatalf("error did not include stdout fallback: %v", err)
	}
	if !strings.Contains(err.Error(), "output: stdout failure") {
		t.Fatalf("error did not label stdout fallback as output: %v", err)
	}
	if strings.Contains(err.Error(), "stderr: stdout failure") {
		t.Fatalf("stdout fallback mislabeled as stderr: %v", err)
	}
}

func TestRunCLICommandBoundsFailureOutput(t *testing.T) {
	for _, mode := range []string{"fail-large-stderr", "fail-large-stdout"} {
		t.Run(mode, func(t *testing.T) {
			bin := writeShelloutHelper(t, mode)
			_, err := RunCLICommand(context.Background(), bin, nil)
			if err == nil {
				t.Fatalf("RunCLICommand %s succeeded unexpectedly", mode)
			}
			if len(err.Error()) > bound.MaxBytes+512 {
				t.Fatalf("failure output was not bounded: %d bytes", len(err.Error()))
			}
			if !strings.Contains(err.Error(), `"truncated":true`) {
				t.Fatalf("bounded failure output did not include a preview envelope: %v", err)
			}
		})
	}
}

func writeShelloutHelper(t *testing.T, mode string) string {
	t.Helper()
	dir := t.TempDir()
	if runtime.GOOS == "windows" {
		path := filepath.Join(dir, "helper.bat")
		var body string
		switch mode {
		case "success":
			body = "@echo off\r\necho telemetry 1>&2\r\necho {\"args\":\"%*\"}\r\n"
		case "fail-stderr":
			body = "@echo off\r\necho boom from stderr 1>&2\r\nexit /b 7\r\n"
		case "fail-stdout":
			body = "@echo off\r\necho stdout failure\r\nexit /b 7\r\n"
		case "fail-large-stderr":
			body = "@echo off\r\npowershell -NoProfile -Command \"[Console]::Error.Write((New-Object string([char]0x78,70000)))\"\r\nexit /b 7\r\n"
		case "fail-large-stdout":
			body = "@echo off\r\npowershell -NoProfile -Command \"[Console]::Out.Write((New-Object string([char]0x78,70000)))\"\r\nexit /b 7\r\n"
		default:
			t.Fatalf("unknown mode %q", mode)
		}
		if err := os.WriteFile(path, []byte(body), 0o755); err != nil {
			t.Fatalf("write helper: %v", err)
		}
		return path
	}
	path := filepath.Join(dir, "helper.sh")
	var body string
	switch mode {
	case "success":
		body = "#!/bin/sh\necho telemetry >&2\nprintf '{\"args\":\"%s\"}\\n' \"$*\"\n"
	case "fail-stderr":
		body = "#!/bin/sh\necho boom from stderr >&2\nexit 7\n"
	case "fail-stdout":
		body = "#!/bin/sh\necho stdout failure\nexit 7\n"
	case "fail-large-stderr":
		body = "#!/bin/sh\nhead -c 70000 /dev/zero | tr '\\000' x >&2\nexit 7\n"
	case "fail-large-stdout":
		body = "#!/bin/sh\nhead -c 70000 /dev/zero | tr '\\000' x\nexit 7\n"
	default:
		t.Fatalf("unknown mode %q", mode)
	}
	if err := os.WriteFile(path, []byte(body), 0o755); err != nil {
		t.Fatalf("write helper: %v", err)
	}
	return path
}

func writeArgvHelper(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	src := filepath.Join(dir, "argvhelper.go")
	body := `package main

import (
	"encoding/json"
	"os"
)

func main() {
	_ = json.NewEncoder(os.Stdout).Encode(os.Args[1:])
}
`
	if err := os.WriteFile(src, []byte(body), 0o644); err != nil {
		t.Fatalf("write argv helper source: %v", err)
	}
	bin := filepath.Join(dir, "argvhelper")
	if runtime.GOOS == "windows" {
		bin += ".exe"
	}
	cmd := exec.Command("go", "build", "-o", bin, src)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build argv helper: %v\n%s", err, out)
	}
	return bin
}

func decodeArgvResult(t *testing.T, result *mcplib.CallToolResult) []string {
	t.Helper()
	var got []string
	if err := json.Unmarshal([]byte(toolResultText(result)), &got); err != nil {
		t.Fatalf("decode argv result: %v; text=%q", err, toolResultText(result))
	}
	return got
}

func toolResultText(result *mcplib.CallToolResult) string {
	if result == nil || len(result.Content) == 0 {
		return ""
	}
	text, ok := result.Content[0].(mcplib.TextContent)
	if !ok {
		return ""
	}
	return text.Text
}

// TestExportOutputFlagIsBlockedForMCP covers the Greptile finding that the
// export command's --output flag reached os.Create with a caller-chosen path.
// export is not annotated mcp:read-only (writing is its job), so the read-only
// write-sink guard never applied to it, and --output is a per-command flag so
// blockedRootFlags did not either. It must be absent from both the tool schema
// and the argv the shell-out layer builds.
func TestExportOutputFlagIsBlockedForMCP(t *testing.T) {
	exportCmd := &cobra.Command{Use: "export", Short: "Export data"}
	var out, format string
	exportCmd.Flags().StringVarP(&out, "output", "o", "", "Output file path (default: stdout)")
	exportCmd.Flags().StringVar(&format, "format", "", "Output format")

	blocked := blockedStructuredArgsForCommand(exportCmd)
	if !blocked["output"] {
		t.Error("export --output is not blocked; an MCP caller could create or truncate any process-writable host file")
	}
	if blocked["format"] {
		t.Error("--format was blocked; only host-file sinks should be")
	}

	argv := cliArgsFromMCP(map[string]any{"output": "/etc/passwd", "format": "json"}, blocked)
	for _, a := range argv {
		if strings.Contains(a, "output") || strings.Contains(a, "/etc/passwd") {
			t.Errorf("argv leaked the blocked output sink: %v", argv)
		}
	}
	joined := strings.Join(argv, " ")
	if !strings.Contains(joined, "format") {
		t.Errorf("argv dropped an allowed flag: %v", argv)
	}
}
